    metaDescription: "모리모리액5 한국신텍스제약 미녹시딜 5% 액제. \"모리모리(많이·풍성하게)\" 일본어 의태어 명명. 같은 회사 모리모리액3 자매 농도 라인 보유. 5%는 남성형 단일, 3%는 남+여 양적응증.",
