    heroDescription: "모리모리액5는 한국신텍스제약(주)이 2020년 10월에 허가받은 미녹시딜 5% 외용액제예요. \"모리모리\"는 일본어 의태어 \"많이·풍성하게\"를 한국식 명명에 가져온 라인이라 \"풍성한 모발\" 이미지를 어필했고, 같은 회사가 모리모리액3을 자매 라인으로 함께 보유한 점이 결정적 차별 포인트예요. 식약처 [02670]모발용제 카테고리 명시 등재.",
