        content: "모리모리액3의 부작용은 식약처 허가사항에 등재된 미녹시딜 외용제 공통 항목을 따라요. 같은 회사 5% 자매 라인보다 농도가 낮아 빈도·강도가 약간 낮은 경향이 있고, 자극으로 5%에서 갈아탄 환자가 3%에서 평가를 완주하는 케이스가 시판 후 자주 보고됐어요.\n\n여성 환자에게 가장 신경 써야 할 부작용은 \"안면털 성장\"이에요. 식약처 허가사항이 부작용 항목에 \"이 약을 바른 부위 이외의 다모증(여성의 경우 안면털 성장)\"을 별도 명시한 건 여성 적응증 라인 공통이에요. 3% 농도라 5%보다 빈도가 낮지만 0이 아니에요. 도포 후 손 두 번 세척과 손톱 밑 청결이 핵심이에요.\n\n드문 전신 부작용으로 흉통·혈압 변화·심박 변화·심계항진·심박동 증가·심낭삼출·호흡곤란이 식약처 허가사항에 등재돼 있어요. 3% 농도라 5%보다 두피 흡수 후 전신 영향이 작지만 0이 아니에요. 두통·어지럼·실신·하지 부종·갑작스런 체중 증가가 새로 생기면 즉시 사용 중단이 원칙이에요.",
