        content: "로게인겔2는 일반의약품 OTC 외용제라 보험 적용 없이 전액 본인 부담이에요. 글로벌 Rogaine 브랜드의 한국 라인이라 같은 5% 미녹시딜 그룹 중 단가가 가장 높은 편이에요 — 다국적 회사 도매 채널이라 국내 신일제약·태극제약·한국신텍스 같은 5% 라인 대비 약국 단가가 높게 형성돼요.\n\n폼 제형 60g 한 캔 기준 남성 1일 2g(약 30일치), 여성 1일 1g(약 60일치) 한도예요. 4개월 평가 표준 기준 남성 약 4캔, 여성 약 2캔이 한 평가 사이클에 필요해요. 단가가 높은 대신 PG 없는 표준 폼 제형이라, 같은 5% 액제 라인에서 자극 빈발해 갈아타는 환자에게는 \"단가↑/자극↓\"가 맞바꿔지는 라인이에요.\n\n글로벌 브랜드 인지도가 높아 약국 입고가 안정적인 점이 단가 외 가치예요. 9년차 시판 라인이라 입고 단절·재고 부족 위험이 국내 후발 라인보다 낮아요. 단가 절감이 우선이면 같은 5% 양적응증 라인 중 마이녹스액5(신일제약, 액제)나 같은 PG 없는 폼 제형의 다른 외산 라인을 비교해볼 수 있어요.",
