        content: "식약처 허가사항 보관 조건은 \"습기와 빛을 피해 실온에서 보관\"이에요. 액제 라인 공통 조건이고, 같은 브랜드 자매 라인 2%·3%·5% 모두 동일한 보관 조건이라, 자매 라인 동시 보유 환자도 같은 위치에 함께 보관할 수 있어요.\n\n에탄올 함유 액제라 식약처 허가사항에 \"화기 근처에 두지 말 것\"이 명시돼 있어요. 라이터·가스레인지·히터 근처 보관 금지가 표준이고, 자동차 실내 같은 고온 환경도 피해야 해요 — 에탄올 증발로 농도가 변할 수 있어요.\n\n어린이 손이 닿지 않는 곳에 보관하고, 같은 브랜드 자매 라인 보유 시 농도 표기(2/3/5)를 잘 보고 사용해요. 자매 라인이 같은 외관·라벨 디자인이라 농도를 혼동하기 쉬운 점이 자매 라인 운영의 단점이라, 보관 시 농도별로 분리 표시하는 게 좋아요. 유통기한 경과 시 약국 폐의약품 수거함에 폐기하는 게 표준이에요.",
