    heroDescription: "다모녹실액3는 (주)티디에스팜이 2020년 3월에 신고한 미녹시딜 3% 외용액제예요. 식약처 허가사항 [02670]모발용제 카테고리 명시 등재 라인이고, 자매 라인 2·3·5% 중 3%는 \"남+여 양적응증\"으로 등재돼 다모녹실 자매 5% 라인이 남성 전용인 점을 보완하는 여성 환자 진입 라인이에요.",
