        content: "다모녹실액3는 (주)티디에스팜의 미녹시딜 3% 외용액제예요. 식약처 허가사항 품목번호 202001674 기준 itemName이 \"다모녹실액3%(미녹시딜)\"로 등재돼 있어요. 식약처 카테고리는 [02670]모발용제(발모, 탈모, 염모, 양모제)로 명시 등재됐고, 같은 자매 라인 다모녹실액5(품목번호 202001675)와 같은 날 함께 신고된 자매 농도 라인이에요.\n\n다모녹실 자매 라인 안에서 식약처 적응증이 농도별로 분리 등재돼 있어요. 다모녹실액3는 \"남성형 및 여성형 탈모증\" 양적응증이고, 자매 다모녹실액5는 \"남성형 단일\"에 \"여성 환자(5%에 한함)\" 금기가 추가돼 있어요. 같은 다모녹실 브랜드 안에서 여성 환자가 사용 가능한 최고 농도가 3%(다모녹실액3)인 구조예요.\n\n부형제는 같은 카테고리 다른 미녹시딜 액제와 동일하게 에탄올과 프로필렌글리콜이 용매로 들어가요. 같은 자매 라인 5%와 부형제·회사·도매 채널이 동일해, 농도만 단일 변수로 다른 갈아타기 비교가 가능한 자매 라인 구조예요.",
