        content: "식약처 허가사항 금기 환자가 명시돼 있어요. 1) 여성·소아 2) 두타스테리드·5α-환원효소 억제제 과민증 환자 3) 중증 간기능 부전 환자가 절대 금기예요. 임부 또는 임신 가능성 있는 여성은 정제 피부 접촉도 피해야 한다고 식약처 허가사항에 명시돼 있어요 — 두타스테리드는 피부 흡수가 가능해 남성 태아 외부 생식기 발달 이상을 초래할 수 있어요.\n\n케이두타다트정은 정제 제형이라 캡슐 누출 위험이 없는 점이 가족 거주 환경 안전성 차별 포인트예요. 같은 두타스테리드 그룹 연질캡슐 라인은 \"누출 시 즉시 물·비누 세척\"이 식약처 허가사항에 명시돼 있는데, 정제는 누출 자체가 발생하지 않아요. 임부·어린이 가족 환자가 정제 라인을 1차 선호하는 이유예요.\n\nPSA 수치가 약 40~50% 감소해요. 전립선암 스크리닝 시 6개월 복용 후 새 PSA 기저치 설정이 권장되고, 검진 전 의사에게 복용 사실을 반드시 알려야 해요. 헌혈은 마지막 복용 후 6개월 경과까지 금지가 식약처 허가사항에 명시돼 있어요. CYP3A4 억제제(케토코나졸·리토나비르·베라파밀·딜티아젬·시메티딘·시프로플록사신 등)와 병용 시 케이두타다트정 혈중 농도 상승 가능성이 있어, 만성 복용 환자는 신중 투여 대상이에요.",
