        content: "유다트정의 주성분은 두타스테리드(Dutasteride) 0.5mg이에요. 식약처 허가사항 기준 [02590]기타의 비뇨생식기관 및 항문용약 카테고리 전문의약품이에요. 이 약은 사실 전립선 질환 치료제(BPH)이고, 탈모 치료 목적 처방은 같은 성분 양적응증 라인 확인이 필요해요.\n\n두타스테리드는 5α-환원효소(1형·2형)를 동시에 억제해서 DHT(디하이드로테스토스테론) 생성을 차단해요. 식약처 허가사항 표준 용법 기준 효과 판단에 최소 6개월 이상 복용이 필요해요.\n\n제형은 정제(tab)예요. 연질캡슐이 다수인 두타스테리드 시장에서 정제 라인이에요. 정제는 씹거나 쪼개지 않고 통째로 삼켜야 해요. 임산부나 임신 가능 여성이 부서지거나 깨진 조각을 취급하면 안 된다고 식약처 허가사항에 명시돼 있어요.",
