        content: "식약처 허가사항 기준 유다트정의 권장용량은 1일 1회 1정(0.5mg) 경구투여예요. 씹거나 쪼개지 않고 통째로 삼켜 복용해야 해요. 식사와 관계없이 복용 가능해요.\n\n신장애 환자나 노인 환자에서 용량 조절 필요가 없어요. 간장애 환자에게 투여한 자료가 없어 권장용량이 확립되지 않았다고 식약처 허가사항에 명시됐어요. 강력한 CYP3A4 억제제(리토나비르 등)를 만성 복용 중인 환자는 주의가 필요해요.\n\n정제를 부수거나 쪼개면 절대 안 돼요. 임산부나 임신 가능 여성이 부서지거나 깨진 조각에 피부가 닿으면 안 된다고 식약처 허가사항에 경고돼 있어요.",
