        content: "식약처 허가사항 금기 환자가 명시돼 있어요. 1) 여성 2) 18세 미만 소아 3) 두타스테리드·다른 5α-환원효소 억제제에 과민증 환자가 절대 금기예요. 임부·임신 가능 여성은 누출되는 캡슐과의 접촉을 피해야 하고, 캡슐이 새어 접촉한 경우 접촉 부위를 즉시 물·비누로 세척해야 한다고 식약처 허가사항에 명시돼 있어요.\n\nPSA 수치가 약 40~50% 감소해요. 전립선암 스크리닝 시 6개월 복용 후 새 PSA 기저치 설정이 권장되고, 검진 전 의사에게 복용 사실을 반드시 알려야 해요. 헌혈은 마지막 복용 후 6개월 경과까지 금지가 식약처 허가사항에 명시돼 있어요. 강력한 CYP3A4 억제제(리토나비르 등) 만성 복용 시 신중 투여 대상이에요.",
