        content: "식약처 허가사항 기준 아이두타연질캡슐의 적응증은 ① 양성 전립선 비대증(BPH) 치료 및 ② 성인 남성(만 18~50세)의 남성형 탈모(androgenetic alopecia) 치료 두 가지예요. BPH+탈모 양적응증으로 허가된 라인이에요.\n\nBPH에서는 전립선 크기를 줄여 배뇨 증상을 개선하고, 급성 요폐 위험과 수술 필요성을 낮춰요. 탈모 치료 효과를 판단하려면 최소 6개월 이상 복용해야 해요. 복용을 중단하면 탈모가 다시 진행되는데, 반감기가 길어서 중단 후에도 당분간 효과가 유지되다 서서히 사라져요.\n\n원형탈모·여성 탈모·출산 관련 탈모에는 허가가 없어요. 피부과나 비뇨기과에서 처방받아야 하는 전문의약품이에요.",
