        content: "아보텍트정의 주성분은 두타스테리드(Dutasteride) 0.5mg이에요. 두타스테리드는 5α-환원효소 1형·2형을 이중 억제해 DHT(디하이드로테스토스테론) 생성을 차단해요. 피나스테리드가 2형만 억제하는 것과 달리 억제 범위가 넓어요.\n\n제형은 정제예요. 연질캡슐과 달리 씹거나 분쇄하지 않고 통째로 삼켜야 해요. 정제를 쪼개거나 분쇄하면 부서진 조각에 약물이 노출돼 임부 피부 접촉 위험이 생겨요.\n\n제조사는 (주)일화이고, 품목번호는 202004082예요. 2020년 5월 허가된 라인으로 e약은요 기준 성분·함량이 검증된 제네릭이에요. 반감기가 약 3~5주로 매우 길어 복용 중단 후에도 체내에서 한참 약효가 유지돼요.",
