        content: "보령두타스테리드연질캡슐의 주성분은 두타스테리드(Dutasteride) 0.5mg이에요. 식약처 허가사항 기준 [02590]기타의 비뇨생식기관 및 항문용약 카테고리 전문의약품이에요. (주)보령이 2019년 허가받은 연질캡슐 라인이에요.\n\n두타스테리드는 5α-환원효소(1형·2형)를 동시에 억제해서 DHT(디하이드로테스토스테론) 생성을 차단해요. 식약처 허가사항 표준 용법 기준 효과 판단에 최소 6개월 이상 복용이 필요해요.\n\n연질캡슐 제형이에요. 두타스테리드 원액(액상)이 오일에 용해돼 캡슐에 담긴 표준 제형으로, 오리지널 아보다트와 같은 제형이에요. 식약처 허가사항에 캡슐 내용물이 노출되면 구강 인두점막 자극을 일으킬 수 있어 씹거나 쪼개지 않고 통째로 삼켜야 한다고 명시돼 있어요.",
