        content: "식약처 허가사항 기준 보령두타스테리드연질캡슐의 적응증은 양성전립선비대증(BPH) 증상 개선·급성 요저류 위험 감소·수술 필요성 감소와 성인 남성(만18~50세)의 남성형 탈모증(안드로젠탈모증) 치료예요. BPH+탈모 양적응증 라인이에요.\n\n치료효과 판단을 위해 최소 6개월 이상 복용이 필요하다고 식약처 허가사항에 명시돼 있어요. 두타스테리드는 반감기가 3~5주로 길어요. 복용 중단 후에도 당분간 약효가 유지되다가 서서히 사라져요.\n\n원형탈모·여성형 탈모·출산 관련 탈모에는 식약처 허가사항 기준 적응증이 없어요. 피부과·비뇨기과 처방이 필요해요.",
