        content: "두타시드정 복용 후 가장 흔히 보고되는 부작용은 성기능 관련 증상이에요. 발기부전, 성욕 감퇴, 사정 장애, 유방 비대/압통이 보고됐어요. 대부분 복용 지속 시 자연 감소하고, 중단 후 회복돼요. 다만 반감기가 3~5주로 길어서 중단 후에도 부작용이 한동안 지속될 수 있어요.\n\n시판 후 보고에서 과민반응(발진, 가려움, 두드러기, 혈관부종), 우울증, 기분 변화, 고환통, 정액 이상이 추가로 보고됐어요. 우울증 병력이 있다면 복용 중 기분 변화를 주의 깊게 관찰해야 해요.\n\nPSA(전립선 특이 항원) 수치가 낮아질 수 있어서, 전립선암 스크리닝 시 복용 중임을 반드시 의사에게 알려야 해요.",
