        content: "두타브정 1정(0.5mg)을 1일 1회 식사와 무관하게 복용해요. 매일 같은 시간에 복용하면 혈중 농도를 안정적으로 유지할 수 있어요. 반감기가 길어서 하루 정도 늦게 복용해도 큰 변화는 없지만, 규칙적인 복용이 기본이에요.\n\n정제를 쪼개거나 분쇄하면 절대 안 돼요. 임산부나 임신 가능성 있는 여성이 분쇄된 약에 피부가 닿으면 남성 태아 생식기 발달에 이상이 생길 수 있어요. 통째로 삼키는 게 원칙이에요.\n\n최소 6개월은 복용해야 효과를 판단할 수 있어요. 증상이 좋아졌다고 임의로 중단하면 전립선이 다시 커지거나 탈모가 재진행돼요. 전문의 지시에 따라 복용 기간을 결정하세요.",
