        content: "식약처 허가사항 기준, 위약대조 4년 임상시험(PLESS)에서 1년차에 발기부전(8.1%), 성욕감퇴(6.4%), 사정량 감소(3.7%)가 보고됐어요. 2~4년차에는 위약군과 차이가 줄어드는 경향이 있고, 복용 중단 후 대부분 회복돼요.\n\n우울한 기분, 우울증, 자살생각을 포함한 기분변형이 보고된 사례가 있어요. 기분 변화가 지속된다면 즉시 복용을 중단하고 전문의와 상담하세요. 유방비대·압통, 과민반응(두드러기, 혈관부종)도 드물게 나타날 수 있어요.\n\nPSA 수치가 낮아질 수 있어요. 전립선암 검진 시 실제보다 낮은 수치가 나올 수 있어서, 검사 전 한국팜비오피나스테리드정 복용 중임을 반드시 의사에게 알려야 해요.",
