        title: "한국팜비오피나스테리드정 주의사항은 무엇인가요?",
        content: "여성과 소아는 한국팜비오피나스테리드정을 절대 복용하면 안 돼요. 임부 또는 임신 가능성이 있는 여성은 분쇄된 정제에 피부가 닿기만 해도 남성 태아 외부 생식기 발달에 이상이 생길 수 있어요.\n\nPSA 수치가 낮아지므로 전립선암 스크리닝 시 6개월 복용 후 새 PSA 기저치를 설정하는 게 권장돼요. 다른 5α-환원효소 억제제(두타스테리드 등)와 동시에 복용하지 마세요.\n\n간 기능에 이상이 있는 분은 의사와 상담 후 복용하세요. 헌혈은 복용 중단 후 최소 1개월 후에 가능해요. 전립선암과 전립선비대증은 증상이 비슷하므로 반드시 비뇨기과에서 정확한 진단을 받아야 해요.",
