        content: "한국팜비오피나스테리드정은 밀폐용기에 넣어 15~30℃ 실온에서 보관해요. 습기와 직사광선을 피하세요. 욕실이나 주방처럼 온도·습도 변화가 심한 곳은 부적합해요.\n\n임산부가 있는 가정에서는 접근이 차단된 별도 공간에 보관하세요. 정제를 분쇄하지 말고 원형 그대로 둬야 해요. 어린이 손이 닿지 않는 높은 곳에 두는 것도 기본이에요.\n\n유통기한이 지난 약은 약국의 폐의약품 수거함에 반납하세요. 다른 약과 한 통에 섞어 보관하면 오용 사고가 생길 수 있어요.",
