        content: "피나신정에 들어있는 피나스테리드 5mg 임상(PLESS 연구)에서 1년차 기준 발기부전(8.1%), 성욕 감퇴(6.4%), 사정량 감소(3.7%)가 보고됐어요. 2~4년차에는 위약군과 차이가 줄어드는 경향이 있어요. 중단 후 대부분 회복돼요.\n\n유방 비대·압통이 드물게 나타날 수 있고, 우울증, 불안, 자살 충동 등 정신과적 증상도 보고됐어요. 기분 변화가 지속되면 즉시 의사에게 알려야 해요.\n\nPSA 수치가 낮아질 수 있어요. 전립선암 검진 시 실제보다 낮은 수치가 나올 수 있어서 검사 전 피나신정 복용 중임을 반드시 의사에게 알려야 해요.",
