        content: "안국피나스테리드정 1정(5mg)을 1일 1회 식사와 무관하게 복용해요. 매일 같은 시간에 복용하면 혈중 농도를 안정적으로 유지할 수 있어요. 아침 또는 저녁 중 편한 시간을 정해서 루틴으로 만드세요.\n\n정제를 쪼개거나 분쇄하면 절대 안 돼요. 코팅이 벗겨지면 임산부나 임신 가능성 있는 여성이 피부를 통해 흡수해서 남성 태아의 생식기 발달에 이상을 일으킬 수 있어요. 복용을 잊었을 때는 생각난 즉시 1정을 복용하고, 다음 복용 시간이 가까우면 건너뛰세요. 2정을 한꺼번에 보충하는 건 금지예요.\n\n최소 6개월은 복용해야 효과를 평가할 수 있어요. 증상이 좋아졌다고 임의로 중단하면 전립선이 다시 커질 수 있어요. 전문의 지시에 따라 복용 기간을 결정하세요.",
